import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define fused CUDA kernel source for LeakyReLU -> sum with tensor -> clamp -> GELU
fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Inline GELU approximation
__device__ __forceinline__ float gelu(float x) {
    const float kAlpha = 0.7071067811865475f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * kAlpha));
}

__global__ void fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ sum_tensor,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    float negative_slope
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * C * D * H * W;
    if (idx < total_size) {
        int w = idx % W;
        int tmp = idx / W;
        int h = tmp % H;
        tmp /= H;
        int d = tmp % D;
        tmp /= D;
        int c = tmp % C;
        // n = tmp / C (not used in the calculations directly here)

        float val = x[idx];
        // LeakyReLU
        if (val < 0.0f) {
            val = negative_slope * val;
        }
        // Add sum_tensor (broadcast on channel dimension)
        val += sum_tensor[c];
        // Clamp
        val = fmaxf(-1.0f, fminf(1.0f, val));
        // GELU
        val = gelu(val);

        out[idx] = val;
    }
}

torch::Tensor fused_operations_cuda(
    torch::Tensor x,
    torch::Tensor sum_tensor,
    float negative_slope
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA tensor");
    TORCH_CHECK(sum_tensor.is_cuda(), "sum_tensor must be CUDA tensor");

    auto out = torch::empty_like(x);
    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    int total_size = N * C * D * H * W;
    const int block_size = 256;
    const int grid_size = (total_size + block_size - 1) / block_size;

    fused_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        sum_tensor.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        negative_slope
    );

    return out;
}
"""

fused_cpp_source = """
torch::Tensor fused_operations_cuda(torch::Tensor x,
                                    torch::Tensor sum_tensor,
                                    float negative_slope);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_operations_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized model that uses a standard 3D conv and a fused CUDA kernel
    for LeakyReLU + sum + clamp + GELU.
    """
    def __init__(self, in_channels, out_channels, kernel_size, sum_tensor_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.sum_tensor = nn.Parameter(torch.randn(sum_tensor_shape, device='cuda'))

    def forward(self, x):
        x = self.conv(x)
        x = fused_ops.fused_operations_cuda(x, self.sum_tensor, 0.2)
        return x
